class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        for i in range(len(nums)):
            for j in range(len(nums)):
                x = nums[i]
                y = nums[j]
                if max(x, y) <= 2 * min(x, y):
                    current = x ^ y
                    if current > max_xor:
                        max_xor = current
        return max_xor
