    def minimizeStringValue(self, s: str) -> str:
        counts = [0] * 26
        for c in s:
            if c != '?':
                counts[ord(c) - ord('a')] += 1

        heap = []
        for i in range(26):
            c = chr(ord('a') + i)
            heapq.heappush(heap, (counts[i], c))

        res = []
        for c in s:
            if c != '?':
                res.append(c)
            else:
                count, char = heapq.heappop(heap)
                res.append(char)
                heapq.heappush(heap, (count + 1, char))

        return ''.join(res)
import heapq

class Solution:
    def minimizeStringValue(self, s: str) -> str:
        counts = [0] * 26
        for c in s:
            if c != '?':
                counts[ord(c) - ord('a')] += 1

        heap = []
        for i in range(26):
            c = chr(ord('a') + i)
            heapq.heappush(heap, (counts[i], c))

        added_letters = []
        for c in s:
            if c == '?':
                count, char = heapq.heappop(heap)
                added_letters.append(char)
                heapq.heappush(heap, (count + 1, char))

        added_letters.sort()

        result = list(s)
        idx = 0
        for i in range(len(result)):
            if result[i] == '?':
                result[i] = added_letters[idx]
                idx += 1

        return ''.join(result)

