        segments = []
        current_segment = []

        for num in nums:
            if (num & k) == k:
                current_segment.append(num)
            else:
                if current_segment:
                    segments.append(current_segment)
                    current_segment = []
        if current_segment:
            segments.append(current_segment)

        count = 0

        for segment in segments:
            prev_ands = []
            for num in segment:
                curr_ands = []
                for val in prev_ands:
                    curr_ands.append(val & num)
                curr_ands.append(num)
                for val in curr_ands:
                    if val == k:
                        count += 1
                prev_ands = curr_ands

        return count
