class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(p) for p in properties]
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # Path compression
                x = parent[x]
            return x

        def union(x, y):
            x_root = find(x)
            y_root = find(y)
            if x_root != y_root:
                parent[y_root] = x_root

        for i in range(n):
            for j in range(i + 1, n):
                common = len(sets[i] & sets[j])
                if common >= k:
                    union(i, j)

        roots = set()
        for i in range(n):
            roots.add(find(i))
