        n = len(properties)
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            x_root = find(x)
            y_root = find(y)
            if x_root == y_root:
                return
            if rank[x_root] < rank[y_root]:
                parent[x_root] = y_root
            else:
                parent[y_root] = x_root
                if rank[x_root] == rank[y_root]:
                    rank[x_root] += 1

        # Precompute sets for each property list
        sets = [set(prop) for prop in properties]

        for i in range(n):
            for j in range(i + 1, n):
                # Check if the intersection of sets[i] and sets[j] is >= k
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        # Count the number of unique roots
        roots = set()
        for x in range(n):
            roots.add(find(x))

        return len(roots)
