class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Precompute the sets for each property list
        sets = [set(prop) for prop in properties]

        # Build the adjacency list
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Find the number of connected components using DFS
        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                # Use DFS to mark all nodes in the current component as visited
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return count
